window.DECK_DATA = window.DECK_DATA || {};
window.DECK_DATA["3"] = [{"n": 1, "mode": "native", "native": "<div class=\"slide-native section-header sm-divider\" style=\"--accent:var(--aws-navy);\"><div class=\"kicker\">Session 3 &middot; Knowledge Check</div><h2>Decoupling, Caching, Auth &amp; Observability</h2><div class=\"sm-divider-meta\">6 questions</div></div>", "nativeClass": "", "image": "", "student": "", "instructor": "", "time": "", "audio": ""}, {"n": 2, "mode": "native", "native": "<div class=\"slide-native sm-skill sm-check\" style=\"--accent:var(--aws-navy);\" data-correct=\"A\" data-multi=\"\" data-rationale=\"SNS fan-out delivers a copy of each message to all subscribers independently. Each Lambda function receives and processes the event separately. If one subscriber fails, the other subscribers still receive and process the message. This provides the required independent parallel processing.\" data-judge=\"{&quot;prompt&quot;: &quot;Question 1: One event, three independent actions&quot;, &quot;options&quot;: [&quot;Create an Amazon SNS topic. Subscribe each Lambda function to the topic. Publish the registration event to the topic.&quot;, &quot;Create an Amazon SQS queue. Configure each Lambda function to poll the same queue for registration events.&quot;, &quot;Create an AWS Step Functions state machine with three parallel branches. Configure each branch to invoke one of the Lambda functions.&quot;, &quot;Create a single Lambda function that calls the three processing functions sequentially using the AWS SDK Invoke API.&quot;], &quot;answer&quot;: &quot;Create an Amazon SNS topic. Subscribe each Lambda function to the topic. Publish the registration event to the topic.&quot;, &quot;why&quot;: &quot;SNS fan-out delivers a copy of each message to all subscribers independently. Each Lambda function receives and processes the event separately. If one subscriber fails, the other subscribers still receive and process the message. This provides the required independent parallel processing.&quot;, &quot;explanations&quot;: {&quot;A&quot;: &quot;SNS fan-out delivers a copy of each message to all subscribers independently. Each Lambda function receives and processes the event separately. If one subscriber fails, the other subscribers still receive and process the message. This provides the required independent parallel processing.&quot;, &quot;B&quot;: &quot;When multiple consumers poll the same SQS queue, each message is delivered to only one consumer. SQS does not deliver copies of a message to multiple consumers simultaneously. Only one of the three functions would process each registration event.&quot;, &quot;C&quot;: &quot;Step Functions parallel states invoke branches simultaneously. However, by default, if one branch fails, the entire parallel state fails. Additional error handling configuration would be needed to ensure independent processing. Also, Step Functions adds orchestration overhead compared to direct event delivery.&quot;, &quot;D&quot;: &quot;Sequential invocation from a single function creates tight coupling. If the coordinating function times out or fails, downstream functions may not be invoked. A failure in one invoke call could prevent subsequent functions from being called. This does not provide independent processing.&quot;}, &quot;sources&quot;: [&quot;https://docs.aws.amazon.com/sns/latest/dg/sns-common-scenarios.html&quot;]}\" data-sources=\"[&quot;https://docs.aws.amazon.com/sns/latest/dg/sns-common-scenarios.html&quot;]\"><div class=\"kicker\">SESSION 3 &middot; KNOWLEDGE CHECK &middot; QUESTION 1 of 6</div><h2>Check yourself <span class=\"sm-check-hint\">click an option</span></h2><p class=\"sm-check-q\">Question 1: One event, three independent actions</p><div class=\"sm-opts\"><button class=\"sm-opt\" data-ltr=\"A\" type=\"button\"><span class=\"sm-opt-l\">A</span><span class=\"sm-opt-t\">Create an Amazon SNS topic. Subscribe each Lambda function to the topic. Publish the registration event to the topic.</span><span class=\"sm-opt-m\"></span></button><button class=\"sm-opt\" data-ltr=\"B\" type=\"button\"><span class=\"sm-opt-l\">B</span><span class=\"sm-opt-t\">Create an Amazon SQS queue. Configure each Lambda function to poll the same queue for registration events.</span><span class=\"sm-opt-m\"></span></button><button class=\"sm-opt\" data-ltr=\"C\" type=\"button\"><span class=\"sm-opt-l\">C</span><span class=\"sm-opt-t\">Create an AWS Step Functions state machine with three parallel branches. Configure each branch to invoke one of the Lambda functions.</span><span class=\"sm-opt-m\"></span></button><button class=\"sm-opt\" data-ltr=\"D\" type=\"button\"><span class=\"sm-opt-l\">D</span><span class=\"sm-opt-t\">Create a single Lambda function that calls the three processing functions sequentially using the AWS SDK Invoke API.</span><span class=\"sm-opt-m\"></span></button></div><div class=\"sm-check-fb\" style=\"display:none\"></div><div class=\"sm-source\"><i class=\"fa-solid fa-circle-question\"></i> Knowledge check &middot; Content Review Session 3</div></div>", "nativeClass": "", "image": "", "student": "", "instructor": "", "time": "", "audio": ""}, {"n": 3, "mode": "native", "native": "<div class=\"slide-native sm-skill sm-check\" style=\"--accent:var(--aws-navy);\" data-correct=\"B\" data-multi=\"\" data-rationale=\"Lazy loading populates the cache on read misses. Setting a TTL of 1 hour provides a safety net for stale data. Invalidating cache keys after the batch update completes ensures that the next read fetches fresh data from the database. This combination minimizes database load during the hour between updates while guaranteeing fresh data after each batch.\" data-judge=\"{&quot;prompt&quot;: &quot;Question 2: Cache a catalog that updates hourly&quot;, &quot;options&quot;: [&quot;Implement a write-through strategy that updates the cache whenever the application writes to the database.&quot;, &quot;Implement a lazy loading strategy with a TTL set to 1 hour. Invalidate the cache keys after the batch process completes.&quot;, &quot;Implement a lazy loading strategy without TTL. Rely on the cache to expire items using the default eviction policy.&quot;, &quot;Implement a write-behind strategy that queues database writes and updates the cache first.&quot;], &quot;answer&quot;: &quot;Implement a lazy loading strategy with a TTL set to 1 hour. Invalidate the cache keys after the batch process completes.&quot;, &quot;why&quot;: &quot;Lazy loading populates the cache on read misses. Setting a TTL of 1 hour provides a safety net for stale data. Invalidating cache keys after the batch update completes ensures that the next read fetches fresh data from the database. This combination minimizes database load during the hour between updates while guaranteeing fresh data after each batch.&quot;, &quot;explanations&quot;: {&quot;A&quot;: &quot;Write-through updates the cache on every write. However, the batch price update process runs against the database directly, not through the application. Write-through only works when all writes go through the application layer. Direct database batch updates would leave the cache stale.&quot;, &quot;B&quot;: &quot;Lazy loading populates the cache on read misses. Setting a TTL of 1 hour provides a safety net for stale data. Invalidating cache keys after the batch update completes ensures that the next read fetches fresh data from the database. This combination minimizes database load during the hour between updates while guaranteeing fresh data after each batch.&quot;, &quot;C&quot;: &quot;Without a TTL or explicit invalidation, cached items persist until memory pressure triggers eviction. After a batch price update, users would continue to see stale prices until the item is evicted. The default eviction policy (allkeys-lru) does not guarantee timely updates after batch processing.&quot;, &quot;D&quot;: &quot;Write-behind (write-back) caching writes to the cache first and asynchronously updates the database. This is useful for write-heavy workloads where the application controls all writes. The batch process updates the database directly, so write-behind would not capture those changes in the cache.&quot;}, &quot;sources&quot;: [&quot;https://docs.aws.amazon.com/whitepapers/latest/database-caching-strategies-using-redis/caching-patterns.html&quot;]}\" data-sources=\"[&quot;https://docs.aws.amazon.com/whitepapers/latest/database-caching-strategies-using-redis/caching-patterns.html&quot;]\"><div class=\"kicker\">SESSION 3 &middot; KNOWLEDGE CHECK &middot; QUESTION 2 of 6</div><h2>Check yourself <span class=\"sm-check-hint\">click an option</span></h2><p class=\"sm-check-q\">Question 2: Cache a catalog that updates hourly</p><div class=\"sm-opts\"><button class=\"sm-opt\" data-ltr=\"A\" type=\"button\"><span class=\"sm-opt-l\">A</span><span class=\"sm-opt-t\">Implement a write-through strategy that updates the cache whenever the application writes to the database.</span><span class=\"sm-opt-m\"></span></button><button class=\"sm-opt\" data-ltr=\"B\" type=\"button\"><span class=\"sm-opt-l\">B</span><span class=\"sm-opt-t\">Implement a lazy loading strategy with a TTL set to 1 hour. Invalidate the cache keys after the batch process completes.</span><span class=\"sm-opt-m\"></span></button><button class=\"sm-opt\" data-ltr=\"C\" type=\"button\"><span class=\"sm-opt-l\">C</span><span class=\"sm-opt-t\">Implement a lazy loading strategy without TTL. Rely on the cache to expire items using the default eviction policy.</span><span class=\"sm-opt-m\"></span></button><button class=\"sm-opt\" data-ltr=\"D\" type=\"button\"><span class=\"sm-opt-l\">D</span><span class=\"sm-opt-t\">Implement a write-behind strategy that queues database writes and updates the cache first.</span><span class=\"sm-opt-m\"></span></button></div><div class=\"sm-check-fb\" style=\"display:none\"></div><div class=\"sm-source\"><i class=\"fa-solid fa-circle-question\"></i> Knowledge check &middot; Content Review Session 3</div></div>", "nativeClass": "", "image": "", "student": "", "instructor": "", "time": "", "audio": ""}, {"n": 4, "mode": "native", "native": "<div class=\"slide-native sm-skill sm-check\" style=\"--accent:var(--aws-navy);\" data-correct=\"A\" data-multi=\"\" data-rationale=\"A Cognito user pool provides a managed user directory with email/password authentication. An identity pool exchanges user pool tokens for temporary AWS credentials scoped to an IAM role. This gives authenticated users direct S3 access without managing infrastructure or credential distribution.\" data-judge=\"{&quot;prompt&quot;: &quot;Question 3: Sign in, then reach S3 as the user&quot;, &quot;options&quot;: [&quot;Create an Amazon Cognito user pool for authentication. Create an identity pool that uses the user pool as an authentication provider. Configure the identity pool to provide temporary AWS credentials with an IAM role that grants S3 access.&quot;, &quot;Deploy an OpenID Connect provider on Amazon EC2. Create a Cognito identity pool that federates with the provider. Configure IAM roles for S3 access.&quot;, &quot;Create IAM users for each application user. Generate access keys for each user. Embed the access keys in the mobile application for S3 access.&quot;, &quot;Create a Lambda function that validates user credentials against a DynamoDB table. Issue custom JWT tokens. Configure S3 bucket policies to validate the JWT on each request.&quot;], &quot;answer&quot;: &quot;Create an Amazon Cognito user pool for authentication. Create an identity pool that uses the user pool as an authentication provider. Configure the identity pool to provide temporary AWS credentials with an IAM role that grants S3 access.&quot;, &quot;why&quot;: &quot;A Cognito user pool provides a managed user directory with email/password authentication. An identity pool exchanges user pool tokens for temporary AWS credentials scoped to an IAM role. This gives authenticated users direct S3 access without managing infrastructure or credential distribution.&quot;, &quot;explanations&quot;: {&quot;A&quot;: &quot;A Cognito user pool provides a managed user directory with email/password authentication. An identity pool exchanges user pool tokens for temporary AWS credentials scoped to an IAM role. This gives authenticated users direct S3 access without managing infrastructure or credential distribution.&quot;, &quot;B&quot;: &quot;Deploying and managing a custom OpenID Connect provider on EC2 requires patching, scaling, and maintaining the authentication server. This adds significant operational overhead compared to using Cognito user pools as the managed user directory.&quot;, &quot;C&quot;: &quot;Creating IAM users for application users does not scale. IAM has account-level limits on the number of users. Embedding long-term access keys in mobile applications is a security risk. If the application binary is decompiled, the keys are exposed. IAM users are for AWS administrative access, not application end users.&quot;, &quot;D&quot;: &quot;S3 bucket policies cannot validate custom JWT tokens. S3 evaluates IAM-based access policies and does not have a mechanism to parse or verify JWT claims in request headers. Additionally, managing a custom authentication system with DynamoDB adds operational overhead.&quot;}, &quot;sources&quot;: [&quot;https://docs.aws.amazon.com/cognito/latest/developerguide/cognito-identity.html&quot;]}\" data-sources=\"[&quot;https://docs.aws.amazon.com/cognito/latest/developerguide/cognito-identity.html&quot;]\"><div class=\"kicker\">SESSION 3 &middot; KNOWLEDGE CHECK &middot; QUESTION 3 of 6</div><h2>Check yourself <span class=\"sm-check-hint\">click an option</span></h2><p class=\"sm-check-q\">Question 3: Sign in, then reach S3 as the user</p><div class=\"sm-opts\"><button class=\"sm-opt\" data-ltr=\"A\" type=\"button\"><span class=\"sm-opt-l\">A</span><span class=\"sm-opt-t\">Create an Amazon Cognito user pool for authentication. Create an identity pool that uses the user pool as an authentication provider. Configure the identity pool to provide temporary AWS credentials with an IAM role that grants S3 access.</span><span class=\"sm-opt-m\"></span></button><button class=\"sm-opt\" data-ltr=\"B\" type=\"button\"><span class=\"sm-opt-l\">B</span><span class=\"sm-opt-t\">Deploy an OpenID Connect provider on Amazon EC2. Create a Cognito identity pool that federates with the provider. Configure IAM roles for S3 access.</span><span class=\"sm-opt-m\"></span></button><button class=\"sm-opt\" data-ltr=\"C\" type=\"button\"><span class=\"sm-opt-l\">C</span><span class=\"sm-opt-t\">Create IAM users for each application user. Generate access keys for each user. Embed the access keys in the mobile application for S3 access.</span><span class=\"sm-opt-m\"></span></button><button class=\"sm-opt\" data-ltr=\"D\" type=\"button\"><span class=\"sm-opt-l\">D</span><span class=\"sm-opt-t\">Create a Lambda function that validates user credentials against a DynamoDB table. Issue custom JWT tokens. Configure S3 bucket policies to validate the JWT on each request.</span><span class=\"sm-opt-m\"></span></button></div><div class=\"sm-check-fb\" style=\"display:none\"></div><div class=\"sm-source\"><i class=\"fa-solid fa-circle-question\"></i> Knowledge check &middot; Content Review Session 3</div></div>", "nativeClass": "", "image": "", "student": "", "instructor": "", "time": "", "audio": ""}, {"n": 5, "mode": "native", "native": "<div class=\"slide-native sm-skill sm-check\" style=\"--accent:var(--aws-navy);\" data-correct=\"A,B\" data-multi=\"1\" data-rationale=\"A CloudWatch alarm evaluates a metric against a threshold over a specified period. Setting the statistic to Average with a period of 300 seconds (5 minutes) and threshold of 5 seconds matches the requirement. Configuring the SNS topic as the alarm action sends the notification when the alarm state changes to ALARM.\" data-judge=\"{&quot;prompt&quot;: &quot;Question 4: Alarm when orders run slow&quot;, &quot;options&quot;: [&quot;Create a CloudWatch alarm on the OrderProcessingTime metric with a threshold of 5 seconds, a period of 5 minutes, and the Average statistic. Configure the alarm action to publish to the SNS topic.&quot;, &quot;Ensure the application publishes the OrderProcessingTime metric data points with the correct namespace and dimensions using the PutMetricData API.&quot;, &quot;Create a CloudWatch Logs metric filter that extracts OrderProcessingTime values from application log entries and creates the custom metric.&quot;, &quot;Create an Amazon EventBridge rule that matches CloudWatch alarm state change events. Configure the rule target to invoke the SNS topic.&quot;, &quot;Configure CloudWatch to use the Sum statistic with a 1-minute period and set the threshold to 25 seconds.&quot;], &quot;answer&quot;: &quot;Create a CloudWatch alarm on the OrderProcessingTime metric with a threshold of 5 seconds, a period of 5 minutes, and the Average statistic. Configure the alarm action to publish to the SNS topic.; Ensure the application publishes the OrderProcessingTime metric data points with the correct namespace and dimensions using the PutMetricData API.&quot;, &quot;why&quot;: &quot;A CloudWatch alarm evaluates a metric against a threshold over a specified period. Setting the statistic to Average with a period of 300 seconds (5 minutes) and threshold of 5 seconds matches the requirement. Configuring the SNS topic as the alarm action sends the notification when the alarm state changes to ALARM.&quot;, &quot;explanations&quot;: {&quot;A&quot;: &quot;A CloudWatch alarm evaluates a metric against a threshold over a specified period. Setting the statistic to Average with a period of 300 seconds (5 minutes) and threshold of 5 seconds matches the requirement. Configuring the SNS topic as the alarm action sends the notification when the alarm state changes to ALARM.&quot;, &quot;B&quot;: &quot;For a CloudWatch alarm to evaluate a custom metric, the application must publish metric data points to CloudWatch using the PutMetricData API. The metric must use a consistent namespace and dimensions so the alarm can locate and evaluate the correct data points.&quot;, &quot;C&quot;: &quot;The question states the application already emits a custom metric named OrderProcessingTime. A metric filter extracts metric data from log entries. Since the application directly publishes the metric, a metric filter is not needed and would create a duplicate metric.&quot;, &quot;D&quot;: &quot;While EventBridge can capture CloudWatch alarm state changes, this adds unnecessary complexity. CloudWatch alarms natively support SNS topics as alarm actions. Direct integration between the alarm and SNS is simpler and does not require an additional EventBridge rule.&quot;, &quot;E&quot;: &quot;Using the Sum statistic would add all processing times together. If 10 orders are processed in 5 minutes each taking 3 seconds, the sum would be 30 seconds and trigger the alarm even though no individual order exceeded 5 seconds. The requirement calls for the Average statistic over a 5-minute period.&quot;}, &quot;sources&quot;: [&quot;https://docs.aws.amazon.com/AmazonCloudWatch/latest/monitoring/AlarmThatSendsEmail.html&quot;]}\" data-sources=\"[&quot;https://docs.aws.amazon.com/AmazonCloudWatch/latest/monitoring/AlarmThatSendsEmail.html&quot;]\"><div class=\"kicker\">SESSION 3 &middot; KNOWLEDGE CHECK &middot; QUESTION 4 of 6</div><h2>Check yourself <span class=\"sm-check-hint\">select all that apply</span></h2><p class=\"sm-check-q\">Question 4: Alarm when orders run slow</p><div class=\"sm-opts\"><button class=\"sm-opt\" data-ltr=\"A\" type=\"button\"><span class=\"sm-opt-l\">A</span><span class=\"sm-opt-t\">Create a CloudWatch alarm on the OrderProcessingTime metric with a threshold of 5 seconds, a period of 5 minutes, and the Average statistic. Configure the alarm action to publish to the SNS topic.</span><span class=\"sm-opt-m\"></span></button><button class=\"sm-opt\" data-ltr=\"B\" type=\"button\"><span class=\"sm-opt-l\">B</span><span class=\"sm-opt-t\">Ensure the application publishes the OrderProcessingTime metric data points with the correct namespace and dimensions using the PutMetricData API.</span><span class=\"sm-opt-m\"></span></button><button class=\"sm-opt\" data-ltr=\"C\" type=\"button\"><span class=\"sm-opt-l\">C</span><span class=\"sm-opt-t\">Create a CloudWatch Logs metric filter that extracts OrderProcessingTime values from application log entries and creates the custom metric.</span><span class=\"sm-opt-m\"></span></button><button class=\"sm-opt\" data-ltr=\"D\" type=\"button\"><span class=\"sm-opt-l\">D</span><span class=\"sm-opt-t\">Create an Amazon EventBridge rule that matches CloudWatch alarm state change events. Configure the rule target to invoke the SNS topic.</span><span class=\"sm-opt-m\"></span></button><button class=\"sm-opt\" data-ltr=\"E\" type=\"button\"><span class=\"sm-opt-l\">E</span><span class=\"sm-opt-t\">Configure CloudWatch to use the Sum statistic with a 1-minute period and set the threshold to 25 seconds.</span><span class=\"sm-opt-m\"></span></button></div><div class=\"sm-check-submit\"><button class=\"sm-submit\" type=\"button\" disabled>Submit</button></div><div class=\"sm-check-fb\" style=\"display:none\"></div><div class=\"sm-source\"><i class=\"fa-solid fa-circle-question\"></i> Knowledge check &middot; Content Review Session 3</div></div>", "nativeClass": "", "image": "", "student": "", "instructor": "", "time": "", "audio": ""}, {"n": 6, "mode": "native", "native": "<div class=\"slide-native sm-skill sm-check\" style=\"--accent:var(--aws-navy);\" data-correct=\"D\" data-multi=\"\" data-rationale=\"CloudWatch investigations can be started from an alarm and use artificial intelligence to gather related metrics, logs, traces, and recent changes across services. The investigation surfaces suggested probable causes, which replaces the manual search the on-call developer performs.\" data-judge=\"{&quot;prompt&quot;: &quot;Question 5: Cut the hunt when an alarm fires&quot;, &quot;options&quot;: [&quot;Create a CloudWatch Logs Insights query that the developer runs against each log group.&quot;, &quot;Configure the alarm to publish to a notification topic so the on-call developer is paged.&quot;, &quot;Enable AWS X-Ray active tracing so the developer can review the trace map after the alarm.&quot;, &quot;Start a CloudWatch investigation from the alarm so that related signals and probable causes are surfaced.&quot;], &quot;answer&quot;: &quot;Start a CloudWatch investigation from the alarm so that related signals and probable causes are surfaced.&quot;, &quot;why&quot;: &quot;CloudWatch investigations can be started from an alarm and use artificial intelligence to gather related metrics, logs, traces, and recent changes across services. The investigation surfaces suggested probable causes, which replaces the manual search the on-call developer performs.&quot;, &quot;explanations&quot;: {&quot;A&quot;: &quot;A Logs Insights query returns results only for the log groups it is run against, and a person runs it and interprets the output. It gathers no metrics or traces and suggests no probable cause.&quot;, &quot;B&quot;: &quot;Publishing the alarm to a notification topic tells the developer that the alarm changed state. It delivers no correlated signals and no suggested cause, so the manual search still follows.&quot;, &quot;C&quot;: &quot;The X-Ray trace map shows service relationships and where faults occur, which is useful evidence, but a person still reads the map and correlates it with metrics and logs. Nothing is gathered or suggested automatically when the alarm triggers.&quot;, &quot;D&quot;: &quot;CloudWatch investigations can be started from an alarm and use artificial intelligence to gather related metrics, logs, traces, and recent changes across services. The investigation surfaces suggested probable causes, which replaces the manual search the on-call developer performs.&quot;}, &quot;sources&quot;: [&quot;https://docs.aws.amazon.com/AmazonCloudWatch/latest/monitoring/Start-Investigation-Alarm.html&quot;]}\" data-sources=\"[&quot;https://docs.aws.amazon.com/AmazonCloudWatch/latest/monitoring/Start-Investigation-Alarm.html&quot;]\"><div class=\"kicker\">SESSION 3 &middot; KNOWLEDGE CHECK &middot; QUESTION 5 of 6</div><h2>Check yourself <span class=\"sm-check-hint\">click an option</span></h2><p class=\"sm-check-q\">Question 5: Cut the hunt when an alarm fires</p><div class=\"sm-opts\"><button class=\"sm-opt\" data-ltr=\"A\" type=\"button\"><span class=\"sm-opt-l\">A</span><span class=\"sm-opt-t\">Create a CloudWatch Logs Insights query that the developer runs against each log group.</span><span class=\"sm-opt-m\"></span></button><button class=\"sm-opt\" data-ltr=\"B\" type=\"button\"><span class=\"sm-opt-l\">B</span><span class=\"sm-opt-t\">Configure the alarm to publish to a notification topic so the on-call developer is paged.</span><span class=\"sm-opt-m\"></span></button><button class=\"sm-opt\" data-ltr=\"C\" type=\"button\"><span class=\"sm-opt-l\">C</span><span class=\"sm-opt-t\">Enable AWS X-Ray active tracing so the developer can review the trace map after the alarm.</span><span class=\"sm-opt-m\"></span></button><button class=\"sm-opt\" data-ltr=\"D\" type=\"button\"><span class=\"sm-opt-l\">D</span><span class=\"sm-opt-t\">Start a CloudWatch investigation from the alarm so that related signals and probable causes are surfaced.</span><span class=\"sm-opt-m\"></span></button></div><div class=\"sm-check-fb\" style=\"display:none\"></div><div class=\"sm-source\"><i class=\"fa-solid fa-circle-question\"></i> Knowledge check &middot; Content Review Session 3</div></div>", "nativeClass": "", "image": "", "student": "", "instructor": "", "time": "", "audio": ""}, {"n": 7, "mode": "native", "native": "<div class=\"slide-native sm-skill sm-check\" style=\"--accent:var(--aws-navy);\" data-correct=\"D\" data-multi=\"\" data-rationale=\"When a Lambda function writes log events as JSON, CloudWatch Logs Insights automatically discovers the top-level JSON keys as queryable fields. The developer can then filter on the customer identifier field and the severity field directly instead of matching text by position, and the events still go to the function&#x27;s existing log group. Position in the line stops mattering because each value is addressed by name.\" data-judge=\"{&quot;prompt&quot;: &quot;Question 6: Find one customer across messy logs&quot;, &quot;options&quot;: [&quot;Increase the retention period of the CloudWatch log group so that more historical log events stay searchable.&quot;, &quot;Create a separate CloudWatch log group for each severity level, and write each plain-text line to its group.&quot;, &quot;Enable AWS X-Ray active tracing on the function, and review the trace map for the customer&#x27;s failed orders.&quot;, &quot;Emit each log event as a structured JSON object with the customer identifier and the severity as named fields.&quot;], &quot;answer&quot;: &quot;Emit each log event as a structured JSON object with the customer identifier and the severity as named fields.&quot;, &quot;why&quot;: &quot;When a Lambda function writes log events as JSON, CloudWatch Logs Insights automatically discovers the top-level JSON keys as queryable fields. The developer can then filter on the customer identifier field and the severity field directly instead of matching text by position, and the events still go to the function&#x27;s existing log group. Position in the line stops mattering because each value is addressed by name.&quot;, &quot;explanations&quot;: {&quot;A&quot;: &quot;Retention controls how long CloudWatch Logs keeps events before deleting them. It makes older events available but does nothing to make the customer identifier or the severity addressable as a field, so the developer still reads unstructured lines.&quot;, &quot;B&quot;: &quot;Splitting by severity moves the log events to new log groups, which the requirement rules out, and it still leaves the customer identifier buried in free text. It also multiplies the log groups the developer must search for a single customer.&quot;, &quot;C&quot;: &quot;The X-Ray trace map shows service relationships and where faults occur, which helps locate a slow or failing dependency. Traces are not log events, so the map cannot filter the function&#x27;s log output by customer identifier or severity.&quot;, &quot;D&quot;: &quot;When a Lambda function writes log events as JSON, CloudWatch Logs Insights automatically discovers the top-level JSON keys as queryable fields. The developer can then filter on the customer identifier field and the severity field directly instead of matching text by position, and the events still go to the function&#x27;s existing log group. Position in the line stops mattering because each value is addressed by name.&quot;}, &quot;sources&quot;: [&quot;https://docs.aws.amazon.com/AmazonCloudWatch/latest/logs/CWL_AnalyzeLogData-discoverable-fields.html&quot;]}\" data-sources=\"[&quot;https://docs.aws.amazon.com/AmazonCloudWatch/latest/logs/CWL_AnalyzeLogData-discoverable-fields.html&quot;]\"><div class=\"kicker\">SESSION 3 &middot; KNOWLEDGE CHECK &middot; QUESTION 6 of 6</div><h2>Check yourself <span class=\"sm-check-hint\">click an option</span></h2><p class=\"sm-check-q\">Question 6: Find one customer across messy logs</p><div class=\"sm-opts\"><button class=\"sm-opt\" data-ltr=\"A\" type=\"button\"><span class=\"sm-opt-l\">A</span><span class=\"sm-opt-t\">Increase the retention period of the CloudWatch log group so that more historical log events stay searchable.</span><span class=\"sm-opt-m\"></span></button><button class=\"sm-opt\" data-ltr=\"B\" type=\"button\"><span class=\"sm-opt-l\">B</span><span class=\"sm-opt-t\">Create a separate CloudWatch log group for each severity level, and write each plain-text line to its group.</span><span class=\"sm-opt-m\"></span></button><button class=\"sm-opt\" data-ltr=\"C\" type=\"button\"><span class=\"sm-opt-l\">C</span><span class=\"sm-opt-t\">Enable AWS X-Ray active tracing on the function, and review the trace map for the customer&#x27;s failed orders.</span><span class=\"sm-opt-m\"></span></button><button class=\"sm-opt\" data-ltr=\"D\" type=\"button\"><span class=\"sm-opt-l\">D</span><span class=\"sm-opt-t\">Emit each log event as a structured JSON object with the customer identifier and the severity as named fields.</span><span class=\"sm-opt-m\"></span></button></div><div class=\"sm-check-fb\" style=\"display:none\"></div><div class=\"sm-source\"><i class=\"fa-solid fa-circle-question\"></i> Knowledge check &middot; Content Review Session 3</div></div>", "nativeClass": "", "image": "", "student": "", "instructor": "", "time": "", "audio": ""}];
